# det: test Delta3 >= c * h targets with c depending on T: e(T) (number of minimal generators of T = <m, A>), mu.
# Reads Q5DUMP lines (m e D3 DEQ h hlo hhi ne2 ne3 dc n2eq n3eq cT r A...).
import sys, collections
from fractions import Fraction as F
def eT(m, A):
    G = sorted(set(A + [m])); mu = G[0]
    # minimal generators: x not in semigroup generated by the smaller ones (bounded check up to max G)
    N = G[-1] + 1; inS = [False] * N; inS[0] = True; mins = []
    for x in range(1, N):
        rep = any(x >= g and inS[x - g] for g in mins)
        if x in G and not rep: mins.append(x); rep = True
        inS[x] = rep
    return len(mins)
rows = []
for fn in sys.argv[1:]:
    for f in fn.split('+'):
        for L in open(f):
            t = L.split()
            if t[0] != 'DUMP': continue
            v = list(map(int, t[1:15])); A = list(map(int, t[15:])); m = v[0]
            rows.append(dict(m=m, e=v[1], D3=v[2], h=v[4], hlo=v[5], hhi=v[6], ne2=v[7], ne3=v[8], mu=A[0], eT=eT(m, A), A=A))
e = rows[0]['e']; print(f"{sys.argv[1]}: {len(rows)} S, e = {e}")
def rep(name, val):
    w = min(rows, key=val); print(f"  min {name} = {float(val(w)):.3f} at m={w['m']} A={w['A']} mu={w['mu']} eT={w['eT']} D3={w['D3']} h={w['h']} hlo={w['hlo']}")
rep('D3/(eT h)', lambda r: F(r['D3'], r['eT'] * r['h']))
rep('D3 - eT h', lambda r: r['D3'] - r['eT'] * r['h'])
rep('D3/(min(mu,e) h)', lambda r: F(r['D3'], min(r['mu'], r['e']) * r['h']))
rep('D3/((eT+2) h)', lambda r: F(r['D3'], (r['eT'] + 2) * r['h']))
rep('D3/((eT+3) h)', lambda r: F(r['D3'], (r['eT'] + 3) * r['h']))
by = collections.defaultdict(list)
for r in rows: by[r['eT']].append(F(r['D3'], r['h']))
print('  min D3/h by eT:', {k: round(float(min(v)), 2) for k, v in sorted(by.items())}, ' counts', {k: len(v) for k, v in sorted(by.items())})
by = collections.defaultdict(list)
for r in rows: by[r['mu']].append(F(r['D3'], r['h']))
print('  min D3/h by mu:', {k: round(float(min(v)), 2) for k, v in sorted(by.items())})
